:root {
  --bg-board: #0d0d1a;
  --bg-header: #12122a;
  --bg-row: #1a1a35;
  --bg-row-alt: #161628;
  --bg-footer: #0f0f20;
  --accent-gold: #f5c518;
  --accent-cyan: #00e5ff;
  --accent-pink: #ff4d8d;
  --accent-purple: #9b59f5;
  --accent-green: #2ecc71;
  --bar-gold: #f5c518;
  --bar-cyan: #00e5ff;
  --bar-pink: #ff4d8d;
  --bar-purple: #9b59f5;
  --text-primary: #ffffff;
  --text-secondary: #8888bb;
  --text-muted: #555580;
  --border-subtle: #2a2a50;
  --rank1-border: #f5c518;
  --rank2-border: #aab0c0;
  --rank3-border: #cd7f32;
  --rank4-border: #2a2a50;
}

.scoreboard {
  width: 480px;
  background: var(--bg-board);
  border-radius: 16px;
  border: 2px solid var(--border-subtle);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.board-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-bottom: 2px solid var(--border-subtle);
}

.header-left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.arcade-icon {
  font-size: 26px;
  line-height: 1;
}

.title-block {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.board-title {
  font-size: 20px;
  font-weight: 900;
  color: var(--accent-cyan);
  letter-spacing: 3px;
  margin: 0;
  line-height: 1;
}

.board-sub {
  font-size: 10px;
  font-weight: 700;
  color: var(--accent-pink);
  letter-spacing: 2px;
  margin: 0;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.round-badge {
  background: var(--accent-purple);
  color: var(--text-primary);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
  padding: 4px 10px;
  border-radius: 20px;
}

.status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--accent-green);
  border: 2px solid var(--bg-header);
  outline: 2px solid var(--accent-green);
}

.scores-grid {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.score-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 16px;
  border-left: 4px solid var(--rank4-border);
  border-bottom: 1px solid var(--border-subtle);
  background: var(--bg-row);
}

.score-row.rank-1 {
  border-left-color: var(--rank1-border);
  background: var(--bg-row);
}

.score-row.rank-2 {
  border-left-color: var(--rank2-border);
  background: var(--bg-row-alt);
}

.score-row.rank-3 {
  border-left-color: var(--rank3-border);
  background: var(--bg-row);
}

.score-row.rank-4 {
  border-left-color: var(--rank4-border);
  background: var(--bg-row-alt);
}

.rank {
  font-size: 12px;
  font-weight: 800;
  color: var(--text-muted);
  width: 22px;
  text-align: center;
  flex-shrink: 0;
}

.rank-1 .rank {
  color: var(--accent-gold);
}

.rank-2 .rank {
  color: var(--rank2-border);
}

.rank-3 .rank {
  color: var(--rank3-border);
}

.player-avatar {
  font-size: 22px;
  line-height: 1;
  flex-shrink: 0;
}

.player-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  width: 80px;
  flex-shrink: 0;
}

.player-name {
  font-size: 13px;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: 1px;
}

.player-tag {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-secondary);
  letter-spacing: 0.5px;
}

.score-block {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1;
}

.score-val {
  font-size: 14px;
  font-weight: 900;
  color: var(--text-primary);
  letter-spacing: 1px;
  text-align: right;
}

.rank-1 .score-val {
  color: var(--accent-gold);
}

.rank-2 .score-val {
  color: var(--accent-cyan);
}

.rank-3 .score-val {
  color: var(--accent-pink);
}

.rank-4 .score-val {
  color: var(--accent-purple);
}

.bar-wrap {
  width: 100%;
  height: 5px;
  background: var(--border-subtle);
  border-radius: 3px;
  overflow: hidden;
}

.bar {
  height: 100%;
  width: var(--w);
  border-radius: 3px;
  background: var(--text-muted);
}

.rank-1 .bar {
  background: var(--bar-gold);
}

.rank-2 .bar {
  background: var(--bar-cyan);
}

.rank-3 .bar {
  background: var(--bar-pink);
}

.rank-4 .bar {
  background: var(--bar-purple);
}

.crown {
  font-size: 16px;
  line-height: 1;
  width: 20px;
  text-align: center;
  flex-shrink: 0;
}

.board-footer {
  background: var(--bg-footer);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 2px solid var(--border-subtle);
}

.footer-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
}

.stat-label {
  font-size: 9px;
  font-weight: 700;
  color: var(--text-muted);
  letter-spacing: 1.5px;
}

.stat-val {
  font-size: 14px;
  font-weight: 900;
  color: var(--text-primary);
  letter-spacing: 1px;
}

.stat-val.timer {
  color: var(--accent-green);
}
